WITH base AS (SELECT *, ADD_MONTHS(last_restock, 6) last_restock_plus_months FROM inventory WHERE MONTH(last_restock) IN (4, 6, 10)), summary AS (SELECT CASE WHEN quantity >= 236 THEN 'high' WHEN quantity >= 95 THEN 'mid' ELSE 'low' END quantity_bucket, ROUND(AVG(quantity), 2) avg_quantity, ROUND(STDDEV(quantity), 2) stddev_quantity FROM base GROUP BY CASE WHEN quantity >= 236 THEN 'high' WHEN quantity >= 95 THEN 'mid' ELSE 'low' END) SELECT * FROM summary WHERE stddev_quantity >= 30 ORDER BY avg_quantity DESC, stddev_quantity;
